-- BTS, MRT, Airport Rail Link and SRT Red Line stations (owner decision,
-- 2026-11-07): a table admin can edit, so new stations can be added as lines
-- open. Seeded from OpenStreetMap route relations (data as of 2026-06-01).
-- OpenStreetMap data is ODbL: pages that use it show
-- "© OpenStreetMap contributors".
-- lines: BTS_SUKHUMVIT, BTS_SILOM, BTS_GOLD, MRT_BLUE, MRT_PURPLE, MRT_YELLOW,
-- MRT_PINK, ARL, SRT_DARK_RED, SRT_LIGHT_RED.

create table public.stations (
  id uuid primary key default gen_random_uuid(),
  name_en text not null check (length(trim(name_en)) between 1 and 80),
  name_th text check (length(name_th) <= 80),
  lines text[] not null check (cardinality(lines) > 0),
  location extensions.geography(point, 4326) not null,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index stations_location_idx on public.stations using gist (location);

create trigger stations_set_updated_at
before update on public.stations
for each row execute function public.set_updated_at();

alter table public.stations enable row level security;
revoke insert, update, delete on public.stations from anon, authenticated;

create policy "Anyone reads active stations"
on public.stations for select to anon, authenticated
using (active);

-- Station list with coordinates, for the home page and admin.
create function public.station_list(p_include_inactive boolean default false)
returns table (
  id uuid, name_en text, name_th text, lines text[],
  lat double precision, lng double precision, active boolean
)
language sql
stable
security invoker
set search_path = ''
as $$
  select s.id, s.name_en, s.name_th, s.lines,
    extensions.st_y(s.location::extensions.geometry),
    extensions.st_x(s.location::extensions.geometry),
    s.active
  from public.stations s
  where s.active or p_include_inactive
  order by s.name_en;
$$;

grant execute on function public.station_list(boolean) to anon, authenticated;

